+  filter?: string,
+  enabled = true,
+  include = 2,
+) => {
   const [data, setData] = useState<T[] | null>(null);
   const [isLoading, setIsLoading] = useState(true);
   const [error, setError] = useState<Error | null>(null);

   useEffect(() => {
+    if (!enabled) {
+      setData(null);
+      setError(null);
+      setIsLoading(false);
