 21	// Mirrors foundation/gridSystem breakpoints.md (768px = 48em). Media queries cannot consume
 22	// CSS vars, so this is the one deliberate exception to the var(--zimm-*) convention (css.md > Tokens).
 23	const TABLET_MIN_WIDTH = '48em';
 24	
 25	const CM_TO_INCH = 0.393701;
 26	
 27	export const convertCm = (n: number) => Math.round(n * CM_TO_INCH * 10) / 10;
 28	
 29	/**
 30	 * Converts a single cell text value from CM to inches when the unit is 'inch'.
 31	 * Handles plain numeric strings (e.g. "76") and en-dash/hyphen ranges (e.g. "86–90").
 32	 * Non-numeric strings (e.g. "AU 6", "XS") are returned unchanged.
 33	 */
 34	export const convertCellText = (text: string, unit: Unit): string => {
 35	  if (unit !== 'inch') return text;
 36	  // Multi-line stacked values (joined by extractCellText) — convert each line independently.
 37	  if (text.includes('\n'))
 38	    return text
 39	      .split('\n')
 40	      .map((line) => convertCellText(line, unit))
 41	      .join('\n');
 42	  const trimmed = text.trim();
 43	  // Strip optional trailing 'cm' unit label (e.g. "56–59cm", "56 - 59 cm") so editors can
 44	  // annotate cells with the unit without breaking numeric detection.
 45	  const hasCmSuffix = /\s*cm$/i.test(trimmed);
 46	  const stripped = hasCmSuffix ? trimmed.replace(/\s*cm$/i, '').trim() : trimmed;
 47	  const rangeMatch = stripped.match(/^(\d+(?:\.\d+)?)\s*[–-]\s*(\d+(?:\.\d+)?)$/);
 48	  if (rangeMatch) {
 49	    const converted = `${convertCm(parseFloat(rangeMatch[1]))}–${convertCm(parseFloat(rangeMatch[2]))}`;
 50	    return hasCmSuffix ? `${converted} in` : converted;
 51	  }
 52	  if (/^\d+(?:\.\d+)?$/.test(stripped)) {
 53	    const converted = String(convertCm(Number(stripped)));
 54	    return hasCmSuffix ? `${converted} in` : converted;
 55	  }
 56	  return text;
 57	};
 58	
 59	/** Recursively extracts plain text from a Rich Text node tree. */
 60	const extractText = (node: ContentfulRichTextNode): string => {
 61	  if (node.nodeType === 'text') return node.value ?? '';
 62	  return (node.content ?? []).map(extractText).join('');
 63	};
 64	
 65	/**
 66	 * Extracts display text from a table cell node.
 67	 * Multiple paragraph children (Contentful stacked values) are joined with '\n'
 68	 * so they render as separate lines when the cell has white-space: pre-line.
 69	 */
 70	const extractCellText = (node: ContentfulRichTextNode): string => {
 71	  if (node.nodeType === 'text') return node.value ?? '';
 72	  const children = node.content ?? [];
 73	  const paragraphs = children.filter((c) => c.nodeType === 'paragraph');
 74	  if (paragraphs.length > 1) {
 75	    return paragraphs
 76	      .map(extractText)
 77	      .filter((t) => t.trim())
 78	      .join('\n');
 79	  }
 80	  return extractText(node);
 81	};
