 69	 */
 70	const extractCellText = (node: ContentfulRichTextNode): string => {
 71	  if (node.nodeType === 'text') return node.value ?? '';
 72	  const children = node.content ?? [];
 73	  const paragraphs = children.filter((c) => c.nodeType === 'paragraph');
 74	  if (paragraphs.length > 1) {
 75	    return paragraphs
 76	      .map(extractText)
 77	      .filter((t) => t.trim())
 78	      .join('\n');
 79	  }
 80	  return extractText(node);
 81	};
 82	
 83	/** Returns true if the Rich Text document contains at least one table node. */
 84	const hasTableNode = (doc: ContentfulRichText): boolean => doc.content.some((n) => n.nodeType === 'table');
 85	
 86	/**
 87	 * Returns true when a table should use the centered grouped layout (Figma "Layout 3").
 88	 *
 89	 * Two cases trigger this:
 90	 * 1. Multiple header rows — the whole table alternates [header, value] pairs in one node.
 91	 * 2. Non-empty first header cell — standard size-guide tables always have an empty first
 92	 *    header cell (the label column has no heading). When the first header cell contains
 93	 *    text (e.g. "OSFA", "S/M") it means all columns are equal-width data, not label+data.
 94	 *    This covers the case where the rich text contains multiple separate small tables
 95	 *    (one per group), each with only one header row.
 96	 *
 97	 * Uses `every` (not `some`) so a mixed row — where only the first cell is a header cell
 98	 * (Contentful's "header column" option) — is not misclassified as a header row.
 99	 */
100	
101	/** True when every cell in a row is a table-header-cell (i.e. a true header row). */
102	const isHeaderRow = (row: ContentfulRichTextNode): boolean => {
103	  const cells = row.content ?? [];
104	  return cells.length > 0 && cells.every((c) => c.nodeType === 'table-header-cell');
105	};
106	
107	export const isGroupedTableNode = (node: ContentfulRichTextNode): boolean => {
108	  const rows = (node.content ?? []).filter((r) => r.nodeType === 'table-row');
109	  const headerRows = rows.filter(isHeaderRow);
110	  if (headerRows.length > 1) return true;
111	  const firstHeader = headerRows[0];
112	  if (!firstHeader) return false;
113	  const firstCellText = extractText((firstHeader.content ?? [])[0] ?? { nodeType: 'text', value: '' }).trim();
114	  // Grouped layout (Figma Layout 3) has a non-empty first header cell AND exactly one body row
115	  // per sub-table. Standard multi-row tables (e.g. Rings, Cuff Bracelets) have a non-empty
116	  // first header cell too — the body-row count is what distinguishes them.
117	  const bodyRowCount = rows.length - headerRows.length;
118	  return firstCellText !== '' && bodyRowCount === 1;
119	};
120	
121	/**
122	 * Renders a Figma "Layout 3" grouped size table.
123	 *
124	 * Each pair of consecutive rows (header + value) forms one group, rendered as an
125	 * independent semantic <table> so screen readers associate header cells with their data
126	 * cells. Columns share width equally via the browser's default table layout — each table
127	 * has a consistent column count within its rows, so no colspan arithmetic is needed even
128	 * though different groups have different counts (OSFA=1, S/M+M/L=2, S+M+L=3).
129	 *
130	 * When the rich text contains separate table nodes per group (the Contentful authoring
131	 * pattern), each call to GroupedSizeTable handles one table node (one group). The outer
132	 * renderRichText VStack provides spacing between tables in that case, and the inner VStack
133	 * here is a transparent no-op with a single child. When all groups are in one table node
134	 * (alternating header/value rows), the inner VStack provides the inter-group gap.
135	 */
136	const GroupedSizeTable = ({ node, unit }: { node: ContentfulRichTextNode; unit: Unit }) => {
137	  const allRows = (node.content ?? []).filter((r) => r.nodeType === 'table-row');
138	  const groups: ContentfulRichTextNode[][] = [];
139	  for (let i = 0; i < allRows.length; i += 2) groups.push(allRows.slice(i, i + 2));
140	
141	  return (
142	    <VStack align="stretch" spacing="var(--zimm-scale-xl)" width="100%">
143	      {groups.map((group, gi) => {
144	        const groupHeaderRows = group.filter(isHeaderRow);
145	        const groupBodyRows = group.filter((r) => !isHeaderRow(r));
146	        return (
147	          <chakra.table key={gi} width="100%" sx={{ borderCollapse: 'collapse', 'td, th': { whiteSpace: 'pre-line' } }}>
148	            {groupHeaderRows.length > 0 && (
149	              <chakra.thead>
150	                {groupHeaderRows.map((row, ri) => (
151	                  <chakra.tr key={ri}>
152	                    {(row.content ?? []).map((c, j) => (
153	                      <chakra.th
154	                        key={j}
155	                        textAlign="center"
156	                        textStyle="navigation"
157	                        color="var(--zimm-color-text-default)"
158	                        paddingX="var(--zimm-scale-2xs)"
159	                        paddingY="var(--zimm-scale-xl)"
160	                        borderBottom={BORDER_FOCUS}
161	                      >
162	                        {convertCellText(extractCellText(c), unit)}
163	                      </chakra.th>
164	                    ))}
165	                  </chakra.tr>
166	                ))}
167	              </chakra.thead>
168	            )}
169	            {groupBodyRows.length > 0 && (
170	              <chakra.tbody>
171	                {groupBodyRows.map((row, ri) => (
172	                  <chakra.tr key={ri}>
173	                    {(row.content ?? []).map((c, j) => (
174	                      <chakra.td
175	                        key={j}
176	                        textAlign="center"
177	                        textStyle="caption"
178	                        color="var(--zimm-color-text-default)"
179	                        paddingX="var(--zimm-scale-2xs)"
180	                        paddingY="var(--zimm-scale-xl)"
181	                        borderBottom={BORDER_SECONDARY}
182	                      >
183	                        {convertCellText(extractCellText(c), unit)}
184	                      </chakra.td>
185	                    ))}
186	                  </chakra.tr>
187	                ))}
188	              </chakra.tbody>
189	            )}
190	          </chakra.table>
191	        );
192	      })}
193	    </VStack>
194	  );
195	};
196	
197	type NavItemProps = { label: string; active: boolean; onClick: () => void };
198	type UnitToggleProps = { unit: Unit; onChange: (u: Unit) => void };
199	
200	const NavItem = ({ label, active, onClick }: NavItemProps) => (
201	  <chakra.button
202	    height="var(--zimm-scale-xl)"
203	    display="flex"
204	    flexDirection="column"
205	    alignItems="flex-start"
206	    justifyContent="center"
207	    flexShrink={0}
208	    sx={{ background: 'none', padding: 0, borderWidth: 0, cursor: 'pointer' }}
209	    aria-pressed={active}
210	    onClick={onClick}
211	  >
212	    <chakra.span
213	      display="flex"
214	      alignItems="center"
215	      paddingY="var(--zimm-scale-2xs)"
216	      sx={{
217	        borderBottomWidth: active ? 'var(--zimm-border-width-default)' : 0,
218	        borderBottomStyle: 'solid',
219	        borderBottomColor: active ? 'var(--zimm-color-border-focus)' : 'transparent',
220	      }}
221	    >
222	      <chakra.span textStyle="navigation" color="var(--zimm-color-text-default)" sx={{ whiteSpace: 'nowrap' }}>
223	        {label}
224	      </chakra.span>
225	    </chakra.span>
226	  </chakra.button>
227	);
228	
229	const UnitToggle = ({ unit, onChange }: UnitToggleProps) => (
230	  <Flex gap="var(--zimm-scale-2xs)" role="group" aria-label="Unit" align="center">
231	    <NavItem label="CM" active={unit === 'cm'} onClick={() => onChange('cm')} />
232	    <chakra.span
233	      height="var(--zimm-scale-xl)"
234	      display="flex"
235	      flexDirection="column"
236	      alignItems="flex-start"
237	      justifyContent="center"
238	      flexShrink={0}
239	    >
240	      <chakra.span display="flex" alignItems="center" paddingY="var(--zimm-scale-2xs)">
241	        <chakra.span textStyle="navigation" color="var(--zimm-color-text-muted)" aria-hidden="true">
242	          |
243	        </chakra.span>
244	      </chakra.span>
245	    </chakra.span>
246	    <NavItem label="INCH" active={unit === 'inch'} onClick={() => onChange('inch')} />
247	  </Flex>
248	);
249	
250	/**
251	 * Converts a Contentful Rich Text `table` node into ZimmTable props.
252	 *
253	 * Mapping:
254	 *   - The first row containing `table-header-cell` nodes → `columns`
255	 *     (columns[0] = label column header, columns[1..n] = data column headers)
256	 *   - Remaining rows → `rows` where cells[0] → row.label, cells[1..n] → row.cells
257	 *
258	 * Unit conversion is applied to every cell that holds a plain numeric string or a
259	 * CM range (e.g. "86–90"). Non-numeric values (e.g. "AU 6", "XS") pass through unchanged.
260	 */
261	const richTextTableToZimmProps = (node: ContentfulRichTextNode, unit: Unit) => {
262	  const allRows = (node.content ?? []).filter((r) => r.nodeType === 'table-row');
263	  const headerRow = allRows.find(isHeaderRow);
264	  const bodyRows = allRows.filter((r) => !isHeaderRow(r));
265	
266	  const columns = headerRow ? (headerRow.content ?? []).map((c) => extractText(c)) : [];
267	
268	  const rows = bodyRows.map((row) => {
269	    const cells = row.content ?? [];
270	    const label = cells[0] ? convertCellText(extractCellText(cells[0]), unit) : '';
271	    const dataCells = cells.slice(1).map((c) => convertCellText(extractCellText(c), unit));
272	    return { label, cells: dataCells };
273	  });
274	
275	  return { columns, rows };
276	};
277	
278	/** Wraps a table with a right-edge fade on mobile to hint at horizontal scroll. */
279	const ScrollableTable = ({ node, unit }: { node: ContentfulRichTextNode; unit: Unit }) => {
280	  const grouped = isGroupedTableNode(node);
281	  return (
282	    <Box
283	      position="relative"
284	      sx={{
285	        _after: {
286	          content: '""',
287	          position: 'absolute',
288	          top: 0,
289	          right: 0,
290	          bottom: 0,
291	          width: 'calc(var(--zimm-scale-4xl) + var(--zimm-scale-xs))',
292	          pointerEvents: 'none',
293	          zIndex: 1,
294	          background: `linear-gradient(to right, transparent, var(--zimm-color-grey-white))`,
295	          display: grouped ? 'none' : 'block',
296	        },
297	        [`@media (min-width: ${TABLET_MIN_WIDTH})`]: {
298	          _after: { display: 'none' },
299	        },
300	      }}
301	    >
302	      {grouped ? (
303	        <GroupedSizeTable node={node} unit={unit} />
304	      ) : (
305	        <Box overflowX="auto" sx={{ td: { whiteSpace: 'pre-line' } }}>
306	          <ZimmTable {...richTextTableToZimmProps(node, unit)} />
307	        </Box>
308	      )}
309	    </Box>
310	  );
311	};
312	
313	const renderTextNode = (node: ContentfulRichTextNode, i: number): React.ReactNode => {
314	  switch (node.nodeType) {
315	    case 'heading-1':
316	    case 'heading-2':
317	    case 'heading-3':
318	    case 'heading-4':
319	    case 'heading-5':
320	    case 'heading-6':
321	      return (
322	        <chakra.h2 key={i} textStyle="productNames" color="var(--zimm-color-text-default)" margin={0}>
323	          {extractText(node)}
324	        </chakra.h2>
325	      );
326	    case 'paragraph': {
327	      const text = extractText(node);
328	      if (!text.trim()) return null;
329	      return (
330	        <chakra.p key={i} textStyle="caption" color="var(--zimm-color-text-default)" margin={0}>
331	          {(node.content ?? []).map((inline, j) => {
332	            if (inline.nodeType !== 'text') return null;
333	            let child: React.ReactNode = inline.value ?? '';
334	            if (inline.marks?.some((m) => m.type === 'bold')) child = <strong key={j}>{child}</strong>;
335	            if (inline.marks?.some((m) => m.type === 'italic')) child = <em key={j}>{child}</em>;
336	            return <React.Fragment key={j}>{child}</React.Fragment>;
337	          })}
338	        </chakra.p>
339	      );
340	    }
341	    default:
342	      return null;
343	  }
344	};
345	
346	/**
347	 * Renders a Rich Text document with section-aware spacing.
348	 *
349	 * Nodes are grouped into sections — each section ends when a `table` node is encountered.
350	 * Within a section (heading + description paragraphs + table), spacing is tight (`xl`).
351	 * Between sections the gap is wider (`4xl`) to visually separate table groups.
352	 *
353	 * Sections that contain no table and no non-empty text are dropped — this prevents
354	 * Contentful's auto-appended trailing empty paragraphs from creating phantom bottom space
355	 * via the VStack gap that would otherwise apply before an empty last section.
356	 */
357	const renderRichText = (doc: ContentfulRichText, unit: Unit): React.ReactNode => {
358	  const sections: ContentfulRichTextNode[][] = [];
359	  let current: ContentfulRichTextNode[] = [];
360	
361	  for (const node of doc.content) {
362	    current.push(node);
363	    if (node.nodeType === 'table') {
364	      sections.push(current);
365	      current = [];
366	    }
367	  }
368	  if (current.length > 0) sections.push(current);
369	
370	  const visibleSections = sections.filter((section) => {
371	    const hasTable = section.some((n) => n.nodeType === 'table');
372	    const hasText = section.some((n) => n.nodeType !== 'table' && extractText(n).trim() !== '');
373	    return hasTable || hasText;
374	  });
375	
376	  return (
377	    <VStack align="stretch" spacing="var(--zimm-scale-xl)" width="100%">
378	      {visibleSections.map((section, si) => {
379	        const tableNode = section.find((n) => n.nodeType === 'table');
380	        const textNodes = section.filter((n) => n.nodeType !== 'table');
381	        return (
382	          <VStack key={si} align="stretch" spacing="var(--zimm-scale-2xl)" width="100%">
383	            {textNodes.map((node, ni) => renderTextNode(node, ni))}
384	            {tableNode && <ScrollableTable node={tableNode} unit={unit} />}
385	          </VStack>
386	        );
387	      })}
388	    </VStack>
389	  );
390	};
391	
392	/**
393	 * Renders one sizeGuideTable entry — label + toggle row, description, table or fallback image.
394	 *
395	 * Each section owns its own CM/INCH unit state so toggling one section's unit does not
396	 * affect any other section in the same guide.
397	 */
398	const SizeGuideSection = ({ tableEntry }: { tableEntry: SizeGuideTableEntry }) => {
399	  const { fields } = tableEntry;
400	
401	  const rawDefault = fields.defaultUnit;
402	  const initialUnit: Unit =
403	    fields.hasCmInchToggle && (rawDefault === 'cm' || rawDefault === 'inch') ? rawDefault : 'cm';
404	  const [unit, setUnit] = useState<Unit>(initialUnit);
405	
406	  useEffect(() => {
407	    setUnit(initialUnit);
408	  }, [initialUnit]);
409	
410	  const hasTable = !!fields.sizeGuideTable && hasTableNode(fields.sizeGuideTable);
411	
412	  const fallbackAssetUrl = fields.imageFallback?.fields.asset?.fields.file.url;
413	  const fallbackImgBase = fallbackAssetUrl
414	    ? fallbackAssetUrl.startsWith('//')
415	      ? `https:${fallbackAssetUrl}`
416	      : fallbackAssetUrl
417	    : null;
418	
419	  return (
420	    <VStack align="stretch" spacing="var(--zimm-scale-2xl)" width="100%">
421	      {/* Label and toggle on the same row — label left-aligned, toggle right-aligned */}
422	      {(fields.sizeGuideTableLabel || fields.hasCmInchToggle) && (
423	        <Flex justify="space-between" align="center">
424	          {fields.sizeGuideTableLabel && (
425	            <chakra.h2 textStyle="productNames" color="var(--zimm-color-text-default)" margin={0}>
426	              {fields.sizeGuideTableLabel}
427	            </chakra.h2>
428	          )}
429	          {fields.hasCmInchToggle && hasTable && <UnitToggle unit={unit} onChange={setUnit} />}
430	        </Flex>
431	      )}
432	
433	      {fields.sizeGuideTable && renderRichText(fields.sizeGuideTable, unit)}
434	
435	      {!hasTable && fallbackImgBase && (
436	        <chakra.picture display="block" width="100%">
437	          <source
438	            type="image/avif"
439	            srcSet={`${fallbackImgBase}?w=800&fm=avif&q=65 1x, ${fallbackImgBase}?w=1600&fm=avif&q=65 2x`}
440	            sizes={`(min-width: ${TABLET_MIN_WIDTH}) 600px, 100vw`}
441	          />
442	          <chakra.img
443	            src={`${fallbackImgBase}?w=800&fm=webp&q=95`}
444	            srcSet={`${fallbackImgBase}?w=800&fm=webp&q=95 1x, ${fallbackImgBase}?w=1600&fm=webp&q=95 2x`}
445	            sizes={`(min-width: ${TABLET_MIN_WIDTH}) 600px, 100vw`}
446	            alt={
447	              fields.sizeGuideTableLabel ??
448	              fields.imageFallback?.fields.altText ??
449	              fields.imageFallback?.fields.internalTitle ??
450	              ''
451	            }
452	            width="100%"
453	            display="block"
454	            loading="lazy"
455	          />
456	        </chakra.picture>
457	      )}
458	    </VStack>
459	  );
460	};
461	
462	export const SizeGuideContent = ({ sizeFit, sizeGuide }: SizeGuideContentProps) => {
463	  const tables = sizeGuide?.fields.sizeGuideTableReference ?? [];
464	
465	  return (
466	    <VStack align="stretch" spacing="var(--zimm-scale-4xl)" width="100%">
467	      {/* Size & fit copy from SFCC c_sizeFit — rendered directly, no section heading */}
468	      {!isBlankRichText(sizeFit) && <ZimmProductDescription description={sizeFit} />}
469	
470	      {sizeGuide && (
471	        <>
472	          {tables.length > 0 && (
473	            <VStack align="stretch" spacing="var(--zimm-scale-4xl)" width="100%">
474	              {tables.map((tableEntry) => (
475	                <SizeGuideSection key={tableEntry.sys.id} tableEntry={tableEntry} />
476	              ))}
477	            </VStack>
478	          )}
479	        </>
480	      )}
481	    </VStack>
482	  );
483	};

