  1	import React from 'react';
  2	import { chakra, useMultiStyleConfig, VisuallyHidden } from '@chakra-ui/react';
  3	import { BORDER_SECONDARY, BORDER_FOCUS } from './zimmTable.css';
  4	
  5	const ZIMM_TABLE_RECIPE = 'ZimmTable';
  6	
  7	export type ZimmTableRow = {
  8	  label: string;
  9	  cells: readonly (string | number)[];
 10	  spans?: readonly number[];
 11	  /** When true, renders this row as a bold group sub-header (labelless mode only). */
 12	  isHeader?: boolean;
 13	};
 14	
 15	export type ZimmTableProps = {
 16	  columns: readonly string[];
 17	  /** Sub-columns per main column. When > 1, main column headers span this many cells. */
 18	  columnSpan?: number;
 19	  /**
 20	   * Sub-column labels rendered in a second thead row. Each label repeats once per main
 21	   * column group (excluding the label column). The label column spans both header rows
 22	   * via rowSpan=2. Used for the gloves table (S/M | M/L repeating under SHORT/LONG GLOVES).
 23	   */
 24	  subColumns?: readonly string[];
 25	  rows: readonly ZimmTableRow[];
 26	  /**
 27	   * Omits the label column and thead entirely. Rows alternate between isHeader=true
 28	   * (bold group header rendered as th) and isHeader=false (measurement values).
 29	   * Used for the hat table's 3-level grouped layout.
 30	   */
 31	  labelless?: boolean;
 32	  /**
 33	   * Used with labelless: renders vertical cell dividers (borderLeft on non-first cells)
 34	   * instead of row striping. Header rows get a dark bottom border; value rows get a light one.
 35	   */
 36	  bordered?: boolean;
 37	};
 38	
 39	/**
 40	 * Generic data table atom for the Size Guide drawer (SFCC-102).
 41	 * Caller is responsible for passing display-ready values — unit conversion
 42	 * happens upstream in SizeGuideContent, not here.
 43	 *
 44	 * columnSpan enables grouped headers (e.g. belt tables where XS/S spans 2 data columns).
 45	 * row.spans controls per-cell colspan for merged rows. Omitting both fields preserves the
 46	 * standard single-level layout used by clothing/shoe tables.
 47	 */
 48	export const ZimmTable = ({
 49	  columns,
 50	  columnSpan = 1,
 51	  subColumns,
 52	  rows,
 53	  labelless = false,
 54	  bordered = false,
 55	}: ZimmTableProps) => {
 56	  const variant = labelless && bordered ? 'bordered' : labelless ? 'labelless' : 'standard';
 57	  const styles = useMultiStyleConfig(ZIMM_TABLE_RECIPE, { variant });
 58	
 59	  if (labelless && bordered) {
 60	    // Pair consecutive rows into [headerRow, valueRow] groups, separated by a visual gap.
 61	    const groups: ZimmTableRow[][] = [];
 62	    for (let i = 0; i < rows.length; i += 2) groups.push(rows.slice(i, i + 2));
 63	    // Derive total column count from the maximum span sum across all rows.
 64	    const totalCols = Math.max(...rows.map((row) => (row.spans ?? row.cells.map(() => 1)).reduce((a, b) => a + b, 0)));
 65	    return (
 66	      <chakra.table __css={styles.table}>
 67	        <chakra.colgroup>
 68	          {Array.from({ length: totalCols }).map((_, i) => (
 69	            <chakra.col key={i} width={`${(100 / totalCols).toFixed(4)}%`} />
 70	          ))}
 71	        </chakra.colgroup>
 72	        <chakra.tbody>
 73	          {groups.map((group, gi) => (
 74	            <React.Fragment key={gi}>
 75	              {gi > 0 && (
 76	                <chakra.tr>
 77	                  <chakra.td __css={styles.spacerTd} colSpan={totalCols} />
 78	                </chakra.tr>
 79	              )}
 80	              {group.map((row, ri) =>
 81	                row.isHeader ? (
 82	                  <chakra.tr key={ri}>
 83	                    {row.cells.map((cell, j) => (
 84	                      <chakra.th
 85	                        key={j}
 86	                        __css={styles.th}
 87	                        colSpan={row.spans?.[j] ?? 1}
 88	                        textAlign="center"
 89	                        borderBottom={BORDER_FOCUS}
 90	                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
 91	                      >
 92	                        {cell}
 93	                      </chakra.th>
 94	                    ))}
 95	                  </chakra.tr>
 96	                ) : (
 97	                  <chakra.tr key={ri}>
 98	                    {row.cells.map((cell, j) => (
 99	                      <chakra.td
100	                        key={j}
101	                        __css={styles.td}
102	                        colSpan={row.spans?.[j] ?? 1}
103	                        textAlign="center"
104	                        borderBottom={BORDER_SECONDARY}
105	                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
106	                      >
107	                        {cell}
108	                      </chakra.td>
109	                    ))}
110	                  </chakra.tr>
111	                ),
112	              )}
113	            </React.Fragment>
114	          ))}
115	        </chakra.tbody>
116	      </chakra.table>
117	    );
118	  }
119	
120	  if (labelless) {
121	    return (
122	      <chakra.table __css={styles.table}>
123	        <chakra.tbody>
124	          {rows.map((row, i) =>
125	            row.isHeader ? (
126	              <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
127	                {row.cells.map((cell, j) => (
128	                  <chakra.th
129	                    key={j}
130	                    __css={styles.th}
131	                    colSpan={row.spans?.[j] ?? 1}
132	                    textAlign="center"
133	                    borderBottom={BORDER_SECONDARY}
134	                  >
135	                    {cell}
136	                  </chakra.th>
137	                ))}
138	              </chakra.tr>
139	            ) : (
140	              <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
141	                {row.cells.map((cell, j) => (
142	                  <chakra.td
143	                    key={j}
144	                    __css={styles.td}
145	                    colSpan={row.spans?.[j] ?? 1}
