SP=/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/f4fc660b-0396-4ce0-8bd7-6beea9f49af7/scratchpad && cat > "$SP/drawer.mjs" <<'EOF'
import {chromium} from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs';
const BASE='https://zimmermann-pr-f102-a6ef9fe5.sfdc-8tgtt5-ecom1.exp-delivery.com';
const pid=process.argv[2]; const W=+(process.argv[3]||1440); const H=+(process.argv[4]||1000);
const b=await chromium.launch();
const p=await (await b.newContext({viewport:{width:W,height:H}})).newPage();
await p.goto(`${BASE}/product/${pid}`,{waitUntil:'domcontentloaded',timeout:60000});
await p.waitForTimeout(6000);
// click the SIZE GUIDE trigger
const btn = p.getByRole('button',{name:/^Size Guide$/i}).first();
const n = await btn.count();
if(!n){ console.log('NO Size Guide button'); await b.close(); process.exit(0); }
await btn.click();
await p.waitForTimeout(4000);
const d = await p.evaluate(()=>{
  const dlg=document.querySelector('[role=dialog]');
  if(!dlg) return {err:'no dialog'};
  const tabs=[...dlg.querySelectorAll('[role=tab],button')].map(e=>({t:e.getAttribute('role'),txt:(e.innerText||'').trim().slice(0,40),sel:e.getAttribute('aria-selected'),press:e.getAttribute('aria-pressed')})).filter(x=>x.txt);
  const tables=[...dlg.querySelectorAll('table')].map(tb=>({
    rows: tb.rows.length,
    cols: tb.rows[0]?.cells.length ?? 0,
    ths: tb.querySelectorAll('th').length,
    thScope: [...tb.querySelectorAll('th')].map(t=>t.getAttribute('scope')),
    firstRow: [...(tb.rows[0]?.cells||[])].map(c=>c.innerText.trim().slice(0,14)),
    secondRow: [...(tb.rows[1]?.cells||[])].map(c=>({tag:c.tagName, v:c.innerText.trim().slice(0,14)})),
    scrollW: tb.scrollWidth, clientW: tb.parentElement?.clientWidth,
    overflowX: tb.parentElement ? getComputedStyle(tb.parentElement).overflowX : null,
  }));
  return {
    dialogText: dlg.innerText.slice(0,900),
    tabs, tables,
    imgs: [...dlg.querySelectorAll('img')].map(i=>({alt:i.alt, src:i.src.slice(0,70)})),
    headings: [...dlg.querySelectorAll('h1,h2,h3')].map(h=>h.tagName+':'+h.innerText.trim().slice(0,40)),
    links: [...dlg.querySelectorAll('a')].map(a=>a.innerText.trim().slice(0,30)),
  };
});
console.log(JSON.stringify(d,null,1));
await p.screenshot({path:`${process.env.SP}/shots/${pid}-${W}-drawer.png`, fullPage:false});
await b.close();
EOF
SP="$SP" node "$SP/drawer.mjs" 0932DSS264 1440 1000 2>&1 | tail -80

