      outline:`${cs.outlineWidth}/${cs.outlineStyle}/${cs.outlineColor}`, shadow:cs.boxShadow.slice(0,40)};});
  if(s) seen.push(s);
}
// dedupe consecutive
const out=[]; seen.forEach(s=>{ if(!out.length||JSON.stringify(out[out.length-1])!==JSON.stringify(s)) out.push(s);});
out.forEach(s=>console.log(`${(s.txt||'(none)').padEnd(20)} ${s.tag.padEnd(7)} role=${String(s.role).padEnd(8)} outline=${s.outline}  shadow=${s.shadow}`));
await b.close();
