  const makeRegion = (siteId: string) => ({
    sys: { id: `region-${siteId}`, contentType: { sys: { id: 'region' as const } } },
    fields: { siteId, label: siteId },
  });

  const makeEntry = (key: string, regions?: ReturnType<typeof makeRegion>[]) => ({
    sys: { id: key, contentType: { sys: { id: 'sizeGuide' as const } } },
    fields: { key, internalTitle: key, sizeGuideTableReference: [], ...(regions ? { regions } : {}) },
  });

  test('global entry (no regions) is eligible for any site', () => {
    const globalEntry = makeEntry('size-guide__womens_dresses');
    mockEntries.mockReturnValue({ data: [globalEntry], isLoading: false });
    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU', 'ZimmermannUS'));
    expect(result.current.sizeGuide?.fields.key).toBe('size-guide__womens_dresses');
  });

  test('region-scoped entry is returned when siteId matches', () => {
    const auEntry = makeEntry('size-guide__womens_dresses', [makeRegion('ZimmermannAU')]);
    const globalEntry = makeEntry('size-guide__womens_dresses');
    mockEntries.mockReturnValue({ data: [globalEntry, auEntry], isLoading: false });
    // auEntry is more specific than globalEntry — should win
    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU', 'ZimmermannAU'));
    expect(result.current.sizeGuide).toEqual(auEntry);
  });

  test('region-scoped entry is excluded when siteId does not match', () => {
    const auEntry = makeEntry('size-guide__womens_dresses', [makeRegion('ZimmermannAU')]);
    const globalEntry = makeEntry('size-guide__womens_dresses');
    mockEntries.mockReturnValue({ data: [auEntry, globalEntry], isLoading: false });
    // US site — AU-scoped entry must be excluded; global fallback must win
    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU', 'ZimmermannUS'));
    expect(result.current.sizeGuide).toEqual(globalEntry);
  });

  test('locale key region match takes priority over global default key', () => {
    const localeAuEntry = makeEntry('size-guide__womens_dresses__en_AU', [makeRegion('ZimmermannAU')]);
    const globalDefault = makeEntry('size-guide__womens_dresses');
    mockEntries.mockReturnValue({ data: [globalDefault, localeAuEntry], isLoading: false });
    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU', 'ZimmermannAU'));
    expect(result.current.sizeGuide).toEqual(localeAuEntry);
  });

  test('falls back to default key when locale key is region-excluded', () => {
    const localeAuEntry = makeEntry('size-guide__womens_dresses__en_AU', [makeRegion('ZimmermannAU')]);
    const globalDefault = makeEntry('size-guide__womens_dresses');
    mockEntries.mockReturnValue({ data: [localeAuEntry, globalDefault], isLoading: false });
    // US site — locale-specific AU entry is excluded; must fall back to global default
    const { result } = renderHook(() => useSizeGuide('womens-dresses-1', 'en-AU', 'ZimmermannUS'));
    expect(result.current.sizeGuide).toEqual(globalDefault);
  });
});
